import { test, expect } from 'claude-code/testing'
// @ts-ignore: plain JS modules
import { renderGoldens } from './goldens/render.js'
// @ts-ignore: generated by scripts/export-goldens.mjs
import { EXPECTED } from './goldens/expected.js'

// The Go package is tested against goldens the JS components draw (scripts/export-goldens.mjs). A change that moves a
// component's drawing makes them stale: this fails until node scripts/export-goldens.mjs writes them again, so Go's
// golden test then shows where Go no longer matches. The same check as export-goldens --check, which needs files
const drawn = renderGoldens()

test('every golden case has a golden', async () => {
    expect(drawn.map((g: any) => g.name).sort()).toEqual(Object.keys(EXPECTED).sort())
})

for (const g of drawn) {
    test(`golden ${g.name} is up to date (node scripts/export-goldens.mjs)`, async () => {
        expect(g.text).toBe(EXPECTED[g.name]?.text)
        expect(g.style).toBe(EXPECTED[g.name]?.style)
    })
}
